using System;
using System.Collections.Generic;
using System.Data;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using CreatorSettlement;
public static class TestsAdjustment {
 static int passed;static string dir;
 static void Assert(bool value,string name){if(!value)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
 static Sheet Input(object[][] rows){var s=new Sheet{Name="调差回归"};var all=new List<object[]>{new object[]{"任务ID","结算日期","任务名称","任务类型","转化数","单价","打款金额","备注"}};all.AddRange(rows);for(int i=0;i<all.Count;i++){s.Rows[i+1]=new Dictionary<string,Cell>();for(int j=0;j<all[i].Length;j++)s.Rows[i+1][Xlsx.Col(j)]=new Cell{Text=Convert.ToString(all[i][j],CultureInfo.InvariantCulture)};}s.SetHeader(1);return s;}
 static DataRow Row(Model m,string id){return m.Adjust.AsEnumerable().Single(r=>Model.Val(r,"任务ID")==id);}
 static Sheet Read(string file){var sheet=Xlsx.Read(file)[0];sheet.SetHeader(1);return sheet;}
 public static int Main(string[] args){try{CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;dir=args[0];Directory.CreateDirectory(dir);var m=Model.Load(Input(new[]{new object[]{"PARTIAL","2026-10-05","方案甲","星视频",148,27,2743,"部分打款"},new object[]{"PARTIAL","2026-10-06","方案甲","星视频",109,27,2943,"正常打款"},new object[]{"PARTIAL","2026-10-07","方案甲","星视频",1,27,20,"差7元"},new object[]{"OVER","2026-10-05","方案乙","直播",2,10,25,"多打5元"},new object[]{"SMALL","2026-10-05","方案丙","星视频",1,0.03m,0.01m,"差0.02元"},new object[]{"SMALL","2026-10-06","方案丙","星视频",1,0.03m,0.02m,"差0.01元"},new object[]{"EQUAL","2026-10-05","方案丁","视频",1,5,5,"金额一致"}}));
  Assert((decimal)Row(m,"PARTIAL")[4]==1260m,"148 times 27 minus 2743 plus 7 gives 1260");Assert(m.Adjust.AsEnumerable().Count(r=>Model.Val(r,"任务ID")=="PARTIAL")==1,"same task merged once");Assert((decimal)Row(m,"OVER")[4]==-5m,"overpayment produces negative adjustment");Assert((decimal)Row(m,"SMALL")[4]==0.03m,"decimal differences summed exactly");Assert(!m.Adjust.AsEnumerable().Any(r=>Model.Val(r,"任务ID")=="EQUAL"),"equal payment excluded");Assert(Model.Val(Row(m,"PARTIAL"),"备注")=="部分打款；差7元","mismatched row notes retained");Assert(Row(m,"PARTIAL").IsNull(5),"actual debit manual column remains blank");m.SyncFixedToAdjustment();Assert((decimal)Row(m,"PARTIAL")[4]==1260m,"sync without fixed prices uses net difference");m.Check.Rows[0][7]=9999m;m.SyncFixedToAdjustment();Assert((decimal)Row(m,"PARTIAL")[4]==9999m,"explicit fixed price replaces cost without subtracting paid twice");m.SyncFixedToAdjustment();Assert((decimal)Row(m,"PARTIAL")[4]==9999m,"fixed price sync remains idempotent");m.Check.Rows[0][7]=0m;m.SyncFixedToAdjustment();Assert((decimal)Row(m,"PARTIAL")[4]==0m,"explicit zero fixed cost retained");m.Check.Rows[0][7]=DBNull.Value;m.SyncFixedToAdjustment();Assert((decimal)Row(m,"PARTIAL")[4]==1260m,"cleared fixed price restores net difference");m.ExportAdjust(Path.Combine(dir,"adjustment-net.xlsx"));var export=Read(Path.Combine(dir,"adjustment-net.xlsx"));Assert(export.Get(2,"线上成本")=="1260"&&export.Get(3,"线上成本")=="-5"&&export.Get(4,"线上成本")=="0.03","actual export contains net positive negative and decimals");Assert(m.Records.Sum(r=>r.Count*r.Price-r.Paid)==m.Adjust.AsEnumerable().Sum(r=>(decimal)r[4]),"whole synthetic input reconciles with adjustment");
  var day=Model.Load(Input(new[]{new object[]{"DEMO-SETTLEMENT-001","2026-10-05","指定任务","星视频",148,27,2743,""}}));Assert((decimal)Row(day,"DEMO-SETTLEMENT-001")[4]==1253m,"reported single day exactly 1253");
  var full=Model.Load(Input(new[]{new object[]{"CASE","2026-10-08","指定任务","星视频",70,27,1890,""},new object[]{"CASE","2026-10-07","指定任务","星视频",212,27,5724,""},new object[]{"CASE","2026-10-06","指定任务","星视频",109,27,2943,""},new object[]{"CASE","2026-10-05","指定任务","星视频",148,27,2743,""},new object[]{"CASE","2026-10-04","指定任务","星视频",86,27,0,""},new object[]{"CASE","2026-10-03","指定任务","星视频",50,27,0,""},new object[]{"CASE","2026-10-02","指定任务","星视频",55,27,0,""},new object[]{"CASE","2026-10-01","指定任务","星视频",40,27,0,""}}));Assert(full.Records.Sum(r=>r.Count)==770m&&full.Records.Sum(r=>r.Count*r.Price)==20790m&&full.Records.Sum(r=>r.Paid)==13300m,"reference screenshot conversion expected and paid totals");Assert((decimal)Row(full,"CASE")[4]==7490m,"zero payments included in 7490 net adjustment");Assert((decimal)Row(full,"CASE")[4]!=10233m,"old gross exception sum no longer used");full.SyncFixedToAdjustment();Assert((decimal)Row(full,"CASE")[4]==7490m,"no fixed price sync includes zero payment differences");full.Check.Rows[0][7]=100m;full.SyncFixedToAdjustment();Assert((decimal)Row(full,"CASE")[4]==100m,"fixed price override keeps previously confirmed cost rule");full.Check.Rows[0][7]=DBNull.Value;full.SyncFixedToAdjustment();Assert((decimal)Row(full,"CASE")[4]==7490m,"clear override restores complete zero-inclusive net adjustment");

  Console.WriteLine("TOTAL "+passed+" adjustment assertions passed");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
